function a(t){if(t==null||t==="")return null;if(t instanceof Date)return t;if(typeof t=="number")return new Date(t);const n=/[zZ]$|[+-]\d{2}:?\d{2}$/.test(t)?t:`${t}Z`,e=new Date(n);return Number.isNaN(e.getTime())?null:e}function u(t){const r=a(t);return r?r.toLocaleString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:!1}):"--"}function f(t){const r=a(t);if(!r)return"暂无数据";const n=Date.now()-r.getTime(),e=Math.round(n/1e3);if(e<5)return"刚刚";if(e<60)return`${e} 秒前`;const o=Math.round(e/60);if(o<60)return`${o} 分钟前`;const i=Math.round(o/60);if(i<24)return`${i} 小时前`;const s=Math.round(i/24);return s<30?`${s} 天前`:u(t).slice(0,10)}function d(t,r=1){return t==null||Number.isNaN(t)?"--":t.toFixed(r)}function c(t){const r=a(t);return r?r.getTime():null}export{u as a,f as b,d as f,c as t};
